  "content": "1|import type { NextFunction, Request, Response } from 'express';
2|import type { NodeCapability } from '../../shared/nodeCapabilities';
3|import { getRequestDbContextFromInput } from '../../core/database/requestDbContext';
4|import {
5|  canAccessManagedFunction,
6|  parseFunctionAccessControl,
7|} from '../../shared/api/contracts/server-functions/accessControl';
8|import {
9|  hasAdminRole,
10|  normalizeAuthRoles,
11|} from '../middleware/auth.middleware';
12|import { getSessionContextForUser } from '../services/attributes/sessionContext.service';
13|import type { EdgeDbQueryFn } from '../services/server-function.service';
14|import { ServerFunctionService } from '../services/server-function.service';
15|import { managedFunctionRouteRegistry } from '../services/managedFunctionRouteRegistry';
16|import { findManagedFunctionById } from '../domain/functions/functionRepository';
17|import { isHttpError } from '../errors/HttpError';
18|import { assertNodeCapabilityForRoute } from './nodeCapability.middleware';
19|
20|const asRecord = (value: unknown): Record<string, unknown> | null => (
21|  value && typeof value === 'object' && !Array.isArray(value)
22|    ? value as Record<string, unknown>
23|    : null
24|);
25|
26|const edgeService = new ServerFunctionService();
27|
28|type ManagedFunctionProxyOptions = {
29|  activeCapabilities?: readonly NodeCapability[];
30|};
31|
32|export const createManagedFunctionProxyMiddleware = (
33|  edgeDbQuery: EdgeDbQueryFn,
34|  options: ManagedFunctionProxyOptions = {},
35|) => (
36|  async (req: Request, res: Response, next: NextFunction) => {
37|    if (res.headersSent) {
38|      next();
39|      return;
40|    }
41|
42|    const pathname = (req.originalUrl || req.url || '').split('?')[0] || '';
43|    if (!pathname.startsWith('/api') || managedFunctionRouteRegistry.isReservedApiPath(pathname)) {
44|      next();
45|      return;
46|    }
47|
48|    try {
49|      await managedFunctionRouteRegistry.ensureLoaded();
50|      const match = managedFunctionRouteRegistry.resolve(req.method, pathname);
51|      if (!match) {
52|        next();
53|        return;
54|      }
55|
56|      if (options.activeCapabilities) {
57|        const capabilityCheck = assertNodeCapabilityForRoute(
58|          options.activeCapabilities,
59|          pathname,
60|          req.method,
61|        );
62|        if (!capabilityCheck.allowed) {
63|          res.status(capabilityCheck.statusCode).json({
64|            success: false,
65|            error: capabilityCheck.message,
66|          });
67|          return;
68|        }
69|      }
70|
71|      const accessControl = parseFunctionAccessControl(
72|        match.function.access_control ?? match.function.accessControl,
73|      );
74|      const isAuthenticated = Boolean(req.auth?.userId);
75|      const allowed = canAccessManagedFunction({
76|        isAdmin: hasAdminRole(req),
77|        isAuthenticated,
78|        userId: req.auth?.userId,
79|        email: req.auth?.email,
80|        roles: normalizeAuthRoles(req),
81|      }, accessControl);
82|
83|      if (!allowed) {
84|        res.status(isAuthenticated ? 403 : 401).json({
85|          success: false,
86|          error: isAuthenticated
87|            ? 'Forbidden: insufficient permissions for this server function.'
88|            : 'Missing access token.',
89|        });
90|        return;
91|      }
92|
93|      const priorBody = req.body;
94|      if (!req.body || typeof req.body !== 'object' || Array.isArray(req.body)) {
95|        req.body = {};
96|      }
97|
98|      req.params = { ...req.params, ...match.params };
99|      (req.body as Record<string, unknown>).params = {
100|        ...(typeof (req.body as Record<string, unknown>).params === 'object'
101|          && (req.body as Record<string, unknown>).params !== null
102|          && !Array.isArray((req.body as Record<string, unknown>).params)
103|          ? (req.body as Record<string, unknown>).params as Record<string, unknown>
104|          : {}),
105|        ...match.params,
106|      };
107|
108|      if (priorBody && typeof priorBody === 'object' && !Array.isArray(priorBody)) {
109|        const bodyRecord = priorBody as Record<string, unknown>;
110|        if (bodyRecord.body !== undefined) {
111|          (req.body as Record<string, unknown>).body = bodyRecord.body;
112|        }
113|        const incomingParams = asRecord(bodyRecord.params);
114|        if (incomingParams) {
115|          (req.body as Record<string, unknown>).params = {
116|            ...(asRecord((req.body as Record<string, unknown>).params) || {}),
117|            ...incomingParams,
118|          };
119|        }
120|      } else if (req.method !== 'GET' && req.method !== 'DELETE') {
121|        (req.body as Record<string, unknown>).body = priorBody;
122|      }
123|
124|      let executionFunction = match.function;
125|      if (!executionFunction.code?.trim()) {
126|        const loaded = await findManagedFunctionById(executionFunction.id);
127|        if (!loaded?.code?.trim()) {
128|          res.status(500).json({
129|            success: false,
130|            error: 'Managed function source is unavailable.',
131|          });
132|          return;
133|        }
134|        executionFunction = {
135|          ...executionFunction,
136|          code: loaded.code,
137|          language: loaded.language,
138|          test_payload: loaded.test_payload,
139|          runtime_version: loaded.runtime_version,
140|          memory_limit: loaded.memory_limit,
141|          timeout_ms: loaded.timeout_ms,
142|          use_global_config: loaded.use_global_config,
143|          enable_logs: loaded.enable_logs,
144|          cache_enabled: loaded.cache_enabled,
145|          cache_ttl_ms: loaded.cache_ttl_ms,
146|          cache_by_param: loaded.cache_by_param,
147|          cache_by_user: loaded.cache_by_user,
148|          engine_type: loaded.engine_type,
149|          metadata_json: loaded.metadata_json,
150|          access_control: loaded.access_control,
151|        };
152|      }
153|
154|      const runtimeDbContext = getRequestDbContextFromInput({
155|        headers: req.headers as Record<string, unknown>,
156|        query: req.query as Record<string, unknown>,
157|        body: req.body,
158|      });
159|
160|      await edgeService.executeManagedFunction(req, res, executionFunction, edgeDbQuery, {
161|        functionId: executionFunction.id,
162|        actorUserId: req.auth?.userId,
163|        authRoles: normalizeAuthRoles(req),
164|        actorEmail: req.auth?.email,
165|        sessionContextLoader: req.auth?.userId
166|          ? (userId) => getSessionContextForUser(userId, req.auth?.role)
167|          : undefined,
168|        dbContext: runtimeDbContext.dataSourceId || runtimeDbContext.database
169|          ? runtimeDbContext
170|          : undefined,
171|        edgeCache: {
172|          requestMethod: req.method,
173|          requestParams: match.params,
174|          requestQuery: req.query,
175|        },
176|      });
177|    } catch (error) {
178|      if (res.headersSent) {
179|        return;
180|      }
181|      if (isHttpError(error)) {
182|        res.status(error.statusCode).json({
183|          success: false,
184|          error: error.message,
185|          ...error.body,
186|        });
187|        return;
188|      }
189|      const message = error instanceof Error ? error.message : 'Managed function execution failed.';
190|      res.status(500).json({ success: false, error: message });
191|    }
192|  }
193|);
194|"
}
